#include "../../sdk/stream.h"
#include "../../interfaces/keyboard.h"
#include "../../interfaces/text.h"
#include "../../interfaces/io.h"
#include "parser.h"
struct command {struct command *next;char **argv;size_t argc;char *file;unsigned mode;cb_handle_t input,output;uint64_t process;unsigned done;};
static struct cb_client client,keyboard_client,clock_client;
static cb_handle_t memory,keyboard,text,applications,streams,filesystem,clock_handle;
static char cwd[4096]="/",line[CB_FRAME_LIMIT-1024];
static size_t length;
static uint32_t columns;
static struct command *orphans;
static struct cb_keyboard_read keyread={.version={sizeof(struct cb_keyboard_read),1,0},.max_events=32};
static void *allocate(size_t bytes){struct cb_memory_request r={.bytes=bytes};CB_REQUIRE(cb_invoke(&client,memory,(struct cb_interface_id)CB_MEMORY_INTERFACE_ID,CB_MEMORY_ALLOCATE,&r,sizeof(r),0)==CB_OK);struct cb_memory_result result;cb_copy(&result,cb_result(&client),sizeof(result));return (void *)(uintptr_t)result.address;}
static void release(void *p){if(p){struct cb_memory_request r={.address=(uintptr_t)p};CB_REQUIRE(cb_invoke(&client,memory,(struct cb_interface_id)CB_MEMORY_INTERFACE_ID,CB_MEMORY_FREE,&r,sizeof(r),0)==CB_OK);}}
static void output(const char *data,size_t bytes){while(bytes){size_t n=bytes>4096?4096:bytes;CB_REQUIRE(cb_invoke(&client,text,(struct cb_interface_id)CB_TEXT_INTERFACE_ID,CB_TEXT_WRITE,data,n,0)==CB_OK);data+=n;bytes-=n;}}
static void print(const char *s){output(s,cb_length(s));}
static void error(cb_status_t status){static const char *names[]={"ok","permission denied","unavailable","timeout","revoked","bad handle","invalid request","version mismatch","buffer too small","resource failure","provider failed","busy","input reset","name in use","would block","broken pipe","read-only filesystem","not found"};print(status<sizeof(names)/sizeof(names[0])?names[status]:"operation failed");print("\n");}
static uint64_t now(void){CB_REQUIRE(cb_invoke(&clock_client,clock_handle,(struct cb_interface_id)CB_IO_INTERFACE_ID,CB_IO_NOW_NS,NULL,0,0)==CB_OK);uint64_t n;cb_copy(&n,cb_result(&clock_client),8);return n;}
static struct cb_stream_pair pipe_create(void){CB_REQUIRE(cb_invoke(&client,streams,(struct cb_interface_id)CB_STREAM_INTERFACE_ID,CB_STREAM_PIPE,NULL,0,0)==CB_OK);struct cb_stream_pair pair;cb_copy(&pair,cb_result(&client),sizeof(pair));return pair;}
static void close_handle(cb_handle_t *h){if(*h){CB_REQUIRE(cb_system_release(*h)==CB_OK);*h=0;}}
static void prompt(void){print(cwd);print(" > ");}
static void help(void){print("cd  clear  help  exit\n");uint64_t cursor=0;unsigned col=0;for(;;){CB_REQUIRE(cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_LIST,&cursor,8,0)==CB_OK);struct cb_reply_header r;cb_copy(&r,client.result,sizeof(r));if(!r.result_bytes)break;struct cb_application_entry e;cb_copy(&e,cb_result(&client),sizeof(e));cursor=e.cursor;output((const char *)cb_result(&client)+sizeof(e),e.name_bytes);uint32_t width=columns/4;if(!width)width=1;static const char spaces[]="                                                                ";size_t padding=e.name_bytes<width?width-e.name_bytes:1;while(padding){size_t n=padding>sizeof(spaces)-1?sizeof(spaces)-1:padding;output(spaces,n);padding-=n;}if(++col==4){print("\n");col=0;}}if(col)print("\n");}
static cb_status_t launch(struct command *c){unsigned char buffer[CB_FRAME_LIMIT];size_t name=cb_length(c->argv[0]),args=0;for(size_t i=0;i<c->argc;++i)args+=cb_length(c->argv[i])+1;size_t dir=cb_length(cwd),total=sizeof(struct cb_application_launch_streams)+name+args+dir;if(total>sizeof(buffer)-1024)return CB_BAD_REQUEST;struct cb_application_launch_streams request={.base={.version={sizeof(request),1,1},.name_bytes=name,.argc=c->argc,.arguments_bytes=args,.cwd_bytes=dir},.streams={c->input,c->output,0}};
    /* Every command receives a separate stderr pipe shared by the chain. */
    extern cb_handle_t terminal_error_writer;request.streams[2]=terminal_error_writer;cb_copy(buffer,&request,sizeof(request));size_t at=sizeof(request);cb_copy(buffer+at,c->argv[0],name);at+=name;for(size_t i=0;i<c->argc;++i){size_t n=cb_length(c->argv[i])+1;cb_copy(buffer+at,c->argv[i],n);at+=n;}cb_copy(buffer+at,cwd,dir);cb_status_t status=cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_LAUNCH,buffer,total,0);if(!status)cb_copy(&c->process,cb_result(&client),8);return status;
}
cb_handle_t terminal_error_writer;
static cb_status_t pump(cb_handle_t h,int *eof){unsigned char buffer[4096];size_t n=0;cb_status_t status=cb_stream_read(&client,h,buffer,sizeof(buffer),&n,CB_STREAM_NONBLOCK);if(status==CB_WOULD_BLOCK)return CB_OK;if(status)return status;if(!n)*eof=1;else output((const char *)buffer,n);return CB_OK;}
static int key_batch(uint64_t timeout){cb_status_t status=cb_invoke(&keyboard_client,keyboard,(struct cb_interface_id)CB_KEYBOARD_INTERFACE_ID,CB_KEYBOARD_READ,&keyread,sizeof(keyread),timeout?now()+timeout:0);if(status==CB_TIMEOUT)return 0;if(status==CB_INPUT_RESYNC){struct cb_keyboard_batch b;cb_copy(&b,cb_result(&keyboard_client),sizeof(b));keyread.provider_epoch=b.provider_epoch;keyread.after_sequence=b.next_sequence;return 0;}if(status!=CB_OK){print("keyboard input failed\n");cb_exit(status);}return 1;}
static unsigned events(struct cb_keyboard_event *out,size_t max,uint64_t timeout){if(!key_batch(timeout))return 0;struct cb_keyboard_batch batch;cb_copy(&batch,cb_result(&keyboard_client),sizeof(batch));CB_REQUIRE(batch.count<=max && sizeof(batch)+(uint64_t)batch.count*sizeof(*out)<=keyboard_client.bytes-sizeof(struct cb_reply_header));cb_copy(out,(unsigned char *)cb_result(&keyboard_client)+sizeof(batch),batch.count*sizeof(*out));keyread.provider_epoch=batch.provider_epoch;keyread.after_sequence=batch.next_sequence;return batch.count;}
/* One queue spans idle/foreground transitions. Reading a batch advances the
 * provider cursor, so nested execution must retain every unconsumed event. */
static struct cb_keyboard_event queued_keys[32];
static unsigned queued_count,queued_at;
static int next_key(struct cb_keyboard_event *out,uint64_t timeout){if(queued_at==queued_count){queued_count=events(queued_keys,32,timeout);queued_at=0;if(!queued_count)return 0;}*out=queued_keys[queued_at++];return 1;}
static int edit(const struct cb_keyboard_event *e){if(e->kind==CB_KEY_DOWN && e->usage_page==7){if(e->usage==40){print("\n");return 1;}if(e->usage==42 && length){do{--length;}while(length && ((unsigned char)line[length]&0xc0)==0x80);line[length]=0;print("\b \b");}if(e->usage==7 && (e->modifiers&0x11) && !length)return 2;}
    if(e->kind==CB_KEY_TEXT && e->codepoint>=32 && e->codepoint!=127 && length<sizeof(line)-5){uint32_t cp=e->codepoint;char encoded[4];size_t n=0;if(cp<128)encoded[n++]=cp;else if(cp<2048){encoded[n++]=0xc0|(cp>>6);encoded[n++]=0x80|(cp&63);}else if(cp<65536){encoded[n++]=0xe0|(cp>>12);encoded[n++]=0x80|((cp>>6)&63);encoded[n++]=0x80|(cp&63);}else {encoded[n++]=0xf0|(cp>>18);encoded[n++]=0x80|((cp>>12)&63);encoded[n++]=0x80|((cp>>6)&63);encoded[n++]=0x80|(cp&63);}cb_copy(line+length,encoded,n);length+=n;line[length]=0;output(encoded,n);}return 0;}
static void reap_orphans(void){struct command **at=&orphans;while(*at){struct command *c=*at;struct cb_application_ref ref={c->process};cb_status_t status=cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_INFO,&ref,sizeof(ref),0);if(!status){struct cb_application_status s;cb_copy(&s,cb_result(&client),sizeof(s));if(s.state!=CB_APPLICATION_RUNNING && cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_RELEASE,&ref,sizeof(ref),0)==CB_OK){*at=c->next;release(c);continue;}}at=&c->next;}}
static void execute(void){size_t size=length+1;char *storage=allocate(size);struct term_token *tokens=allocate(size*sizeof(*tokens));size_t count=0;struct command *first=NULL,**tail=&first;cb_status_t status=CB_OK;
    if(!term_tokens(line,storage,tokens,size,&count)){error(CB_BAD_REQUEST);goto cleanup;}if(!count)goto cleanup;
    for(size_t i=0;i<count;){struct command *c=allocate(sizeof(*c));c->argv=allocate((count+1)*sizeof(*c->argv));*tail=c;tail=&c->next;while(i<count && tokens[i].kind!=TERM_PIPE){if(tokens[i].kind==TERM_WORD)c->argv[c->argc++]=tokens[i++].text;else {unsigned mode=tokens[i++].kind;if(c->file || i==count || tokens[i].kind!=TERM_WORD){status=CB_BAD_REQUEST;break;}c->file=tokens[i++].text;c->mode=mode==TERM_RECREATE?CB_FILE_RECREATE:CB_FILE_APPEND;}}if(status || !c->argc || (c->file && i<count)){status=CB_BAD_REQUEST;break;}if(i<count && ++i==count){status=CB_BAD_REQUEST;break;}}
    if(status){error(status);goto cleanup;}
    if(!first->next && !first->file){const char *cmd=first->argv[0];if(!__builtin_strcmp(cmd,"exit")){cb_exit(0);}if(!__builtin_strcmp(cmd,"help")){help();goto cleanup;}if(!__builtin_strcmp(cmd,"clear")){CB_REQUIRE(cb_invoke(&client,text,(struct cb_interface_id)CB_TEXT_INTERFACE_ID,CB_TEXT_CLEAR,NULL,0,0)==CB_OK);goto cleanup;}if(!__builtin_strcmp(cmd,"cd")){char path[4096];if(first->argc>2 || !cb_path(path,sizeof(path),cwd,first->argc==2?first->argv[1]:"/")){error(CB_BAD_REQUEST);goto cleanup;}status=cb_fs_call(&client,filesystem,CB_FILESYSTEM_STAT,path,0,0);if(!status){struct cb_filesystem_stat st;cb_copy(&st,cb_result(&client),sizeof(st));if(!st.directory)status=CB_BAD_REQUEST;else cb_copy(cwd,path,cb_length(path)+1);}if(status)error(status);goto cleanup;}}
    /* Resolve every output destination before starting any member of the chain. */
    struct cb_stream_pair input=pipe_create(),out=pipe_create(),err=pipe_create();terminal_error_writer=err.writer;first->input=input.reader;for(struct command *c=first;c;c=c->next){if(c->next){struct cb_stream_pair p=pipe_create();c->output=p.writer;c->next->input=p.reader;}else c->output=out.writer;if(c->file){char path[4096];if(!cb_path(path,sizeof(path),cwd,c->file))status=CB_BAD_REQUEST;else status=cb_fs_call(&client,filesystem,CB_FILESYSTEM_OPEN,path,c->mode,0);if(status)break;close_handle(&c->output);cb_copy(&c->output,cb_result(&client),8);out.writer=0;}}
    if(!status)for(struct command *c=first;c;c=c->next){status=launch(c);if(status)break;}
    for(struct command *c=first;c;c=c->next){if(c->input==input.reader)input.reader=0;if(c->output==out.writer)out.writer=0;close_handle(&c->input);close_handle(&c->output);}close_handle(&input.reader);close_handle(&out.writer);close_handle(&err.writer);terminal_error_writer=0;
    if(status){error(status);close_handle(&input.writer);close_handle(&out.reader);close_handle(&err.reader);for(struct command *c=first;c;c=c->next)if(c->process){struct cb_application_ref ref={c->process};cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_STOP,&ref,sizeof(ref),0);}}else {
        length=0;line[0]=0;size_t pending=0,sent=0;char input_line[sizeof(line)+1];int output_eof=0,error_eof=0;
        for(;;){unsigned running=0;for(struct command *c=first;c;c=c->next)if(!c->done){struct cb_application_ref ref={c->process};CB_REQUIRE(cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_INFO,&ref,sizeof(ref),0)==CB_OK);struct cb_application_status s;cb_copy(&s,cb_result(&client),sizeof(s));if(s.state==CB_APPLICATION_RUNNING)++running;else {c->done=1;CB_REQUIRE(cb_invoke(&client,applications,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID,CB_APPLICATION_RELEASE,&ref,sizeof(ref),0)==CB_OK);c->process=0;if(s.state==CB_APPLICATION_FAULTED)print("application fault\n");}}
            if(!output_eof){cb_status_t s=pump(out.reader,&output_eof);if(s){error(s);output_eof=1;}}if(!error_eof){cb_status_t s=pump(err.reader,&error_eof);if(s){error(s);error_eof=1;}}if(!running && output_eof && error_eof)break;
            if(pending && input.writer){size_t n=0;cb_status_t s=cb_stream_write(&client,input.writer,input_line+sent,pending-sent,&n,CB_STREAM_NONBLOCK);if(!s){sent+=n;if(sent==pending)pending=sent=0;}else if(s!=CB_WOULD_BLOCK){close_handle(&input.writer);pending=sent=0;}}
            struct cb_keyboard_event key;if(next_key(&key,10000000)){int action=edit(&key);if(action==2){close_handle(&input.writer);}else if(action==1){if(input.writer && !pending){cb_copy(input_line,line,length);input_line[length]='\n';pending=length+1;sent=0;length=0;line[0]=0;}else if(input.writer && pending){print("stdin busy; line retained\n");}else {length=0;line[0]=0;}}}
        }
        close_handle(&input.writer);close_handle(&out.reader);close_handle(&err.reader);
    }
cleanup:while(first){struct command *next=first->next;release(first->argv);first->argv=NULL;if(first->process){first->next=orphans;orphans=first;}else release(first);first=next;}release(storage);release(tokens);length=0;line[0]=0;
}
/* Local string comparison avoids a libc dependency. */
int strcmp(const char *a,const char *b){while(*a && *a==*b){++a;++b;}return (unsigned char)*a-(unsigned char)*b;}
__attribute__((noreturn)) void _start(const struct cb_startup *packet){struct cb_application_start start;CB_REQUIRE(cb_application_start(packet,&start));CB_REQUIRE(start.header.cwd_bytes<sizeof(cwd));cb_copy(cwd,start.cwd,start.header.cwd_bytes);cwd[start.header.cwd_bytes]=0;memory=cb_acquire(CB_MEMORY_NAME,(struct cb_interface_id)CB_MEMORY_INTERFACE_ID);keyboard=cb_acquire(CB_KEYBOARD_NAME,(struct cb_interface_id)CB_KEYBOARD_INTERFACE_ID);text=cb_acquire(CB_TEXT_NAME,(struct cb_interface_id)CB_TEXT_INTERFACE_ID);applications=cb_acquire(CB_APPLICATIONS_NAME,(struct cb_interface_id)CB_APPLICATIONS_INTERFACE_ID);streams=cb_acquire(CB_STREAM_NAME,(struct cb_interface_id)CB_STREAM_INTERFACE_ID);filesystem=cb_acquire(CB_FILESYSTEM_NAME,(struct cb_interface_id)CB_FILESYSTEM_INTERFACE_ID);clock_handle=cb_acquire(CB_IO_NAME,(struct cb_interface_id)CB_IO_INTERFACE_ID);CB_REQUIRE(cb_invoke(&client,text,(struct cb_interface_id)CB_TEXT_INTERFACE_ID,CB_TEXT_INFO,NULL,0,0)==CB_OK);struct cb_text_info dimensions;cb_copy(&dimensions,cb_result(&client),sizeof(dimensions));columns=dimensions.columns;prompt();for(;;){reap_orphans();struct cb_keyboard_event key;if(next_key(&key,orphans?10000000:0)){int action=edit(&key);if(action==2)cb_exit(0);if(action==1){execute();prompt();}}}}
